/* Russian text for the miracle catalog on /faith/ru/miracles.html: one entry per item of M, same order; quotes are НРП (bolls.life NRT). */
window.FAITH_MIRACLES_RU = [
// ---------------- ВЕТХИЙ ЗАВЕТ ----------------
{t:"Сотворение словом", r:"Быт. 1", n:"Одиннадцать раз: «И сказал Бог… и стало так». Основополагающее чудо: всё видимое вызвано из невидимого речью.", f:"Евр. 11:3: «Именно верой мы понимаем, что вселенная была создана по повелению Бога». Физика веры, первая страница."},
{t:"Енох взят, не увидев смерти", r:"Быт. 5:24", n:"«Енох ходил с Богом, потом его не стало, потому что Бог взял его».", f:"Евр. 11:5: «Благодаря вере Енох был взят из этого мира, не увидев смерти»."},
{t:"Сарра зачинает в девяносто", r:"Быт. 21:1–2", n:"Омертвевшее чрево ожило; Исаак родился точно в срок, «в то самое время, как обещал ему Бог».", f:"Евр. 11:11 в Синодальном говорит о вере самой Сарры: она «получила силу… ибо знала, что верен Обещавший». В НРП тот же стих говорит о вере Авраама: «он полагался на Того, Кто обещал ему»."},
{t:"Неопалимая купина", r:"Исх. 3:1–6", n:"Огонь, который горит и не сжигает; призвание Моисея начинается с чуда и голоса."},
{t:"Посох становится змеем", r:"Исх. 4:2–5; 7:8–12", n:"Египетские мудрецы повторяют знамение, но посох Аарона проглатывает их посохи."},
{t:"Рука Моисея исцелена от проказы", r:"Исх. 4:6–7", n:"Поражена проказой и исцелена в одно мгновение: знамение, данное, чтобы Израиль поверил (ст. 8)."},
{t:"Десять казней египетских", r:"Исх. 7–12", n:"Вода в кровь, тьма, град и всё остальное: каждый раз объявлено словом заранее и исполнено точно в срок."},
{t:"Расступается Красное море", r:"Исх. 14:21–31", n:"Стена воды справа и слева; Израиль идёт по суше, а войско, которое гонится следом, — нет.", f:"Евр. 11:29: «Верой народ перешел Красное море, как по суше». Та же вода стала смертью для неверующих преследователей."},
{t:"Горькая вода в Мерре стала сладкой", r:"Исх. 15:23–26", n:"Дерево, брошенное в воду, делает её сладкой, и Бог подписывает чудо именем: «Я — Господь, Который исцеляет вас»."},
{t:"Манна с неба", r:"Исх. 16", n:"Хлеб на земле каждое утро сорок лет подряд. Ежедневное, будничное, верное сверхъестественное снабжение."},
{t:"Вода из скалы", r:"Исх. 17:1–7; Чис. 20:8–11", n:"Целый народ и его скот напоены из расколотого камня. Дважды."},
{t:"Победа, пока руки подняты", r:"Исх. 17:8–13", n:"Амалик отступает, пока руки Моисея подняты: ход битвы следует за чем-то невидимым."},
{t:"Мариам исцелена от проказы", r:"Чис. 12:10–15", n:"Поражена за бунт и исцелена после короткой молитвы Моисея: «Боже, прошу, исцели ее!» Четыре слова."},
{t:"Земля поглощает Корея", r:"Чис. 16:28–33", n:"Моисей объявляет знамение заранее, и земля подчиняется сказанному слову."},
{t:"Жезл Аарона расцветает за ночь", r:"Чис. 17:8", n:"Сухое дерево за одну ночь даёт почки, цветы и миндаль."},
{t:"Медный змей: взгляни и живи", r:"Чис. 21:8–9", n:"Ужаленный змеями Израиль исцеляется, просто взглянув на поднятого змея.", f:"Иисус сделал это образом спасающей веры: «как Моисей поднял змея в пустыне… чтобы каждый, кто поверит в Него, имел жизнь вечную» (Ин. 3:14–15). Взгляд веры и был всем рецептом."},
{t:"Ослица Валаама заговорила", r:"Чис. 22:28–30", n:"У Бога нет недостатка в устах."},
{t:"Расступается Иордан", r:"Нав. 3:14–17", n:"Река встаёт стеной, но только после того, как ноги священников коснулись воды.", f:"Вода сдвинулась, когда они вошли, а не раньше. Вера действует первой; путь появляется под шагающей ногой."},
{t:"Падение стен Иерихона", r:"Нав. 6:1–19", n:"Семь дней молчаливого шествия, потом крик, и всё это прежде, чем стены дрогнули.", f:"Евр. 11:30: «Верой упали стены Иерихона после того, как семь дней подряд израильтяне обходили город». Победный крик прозвучал раньше доказательств."},
{t:"Солнце останавливается", r:"Нав. 10:12–14", n:"Иисус Навин на глазах у Израиля говорит солнцу, и день растягивается. «Никогда не было такого дня ни прежде, ни потом — дня, когда Господь послушался человека».", f:"Человек сказал творению, и творение послушалось: у Мк. 11:23 есть ветхозаветный пилотный выпуск."},
{t:"Руно Гедеона", r:"Суд. 6:36–40", n:"Роса на руне и сухая земля, потом наоборот. Бог терпеливо выращивает из испуганного человека избавителя."},
{t:"Триста обращают в бегство войско", r:"Суд. 7", n:"Факелы, рога и крик: «Меч за Господа и за Гедеона!» Сказано прежде, чем пал хоть один враг."},
{t:"Сила Самсона", r:"Суд. 14–16", n:"Лев, разорванный голыми руками, тысяча сражённых, городские ворота, унесённые в гору: сила связана с посвящением, утрачена вместе с ним и возвращена после последней молитвы."},
{t:"Дагон падает ниц", r:"1 Цар. 5:1–4", n:"Идола находят лежащим лицом вниз перед ковчегом, дважды, и во второй раз он разбит."},
{t:"Давид и Голиаф", r:"1 Цар. 17", n:"Мальчик бежит навстречу великану с пращой и пятью камнями.", f:"Давид проговорил развязку заранее: «Сегодня Господь отдаст тебя мне» (ст. 46). Он вспомнил прошлые победы, произнёс исход и побежал навстречу проблеме."},
{t:"Илия закрывает небо словом", r:"3 Цар. 17:1", n:"«В эти годы не будет ни росы, ни дождя, разве только по моему слову». Погода три с половиной года подчиняется сказанной фразе.", f:"Иак. 5:17 настаивает, что «Илия был таким же человеком, как и мы»: смысл истории в том, что её можно повторить."},
{t:"Вороны кормят Илию", r:"3 Цар. 17:2–6", n:"Хлеб и мясо утром и вечером, с доставкой птицами."},
{t:"Мука и масло, которые не кончались", r:"3 Цар. 17:8–16", n:"Последняя горсть муки голодающей вдовы переживает голод.", f:"Сначала ей пришлось испечь лепёшку для пророка: поступить по слову, пока кадка ещё выглядела пустой. Запас шёл следом за поступком веры, порция за порцией."},
{t:"Воскрешение сына вдовы", r:"3 Цар. 17:17–24", n:"Первое воскрешение из мёртвых в Писании, через настойчивую молитву человека, простёршегося над мальчиком."},
{t:"Огонь на Кармиле", r:"3 Цар. 18:36–39", n:"Одна тихая молитва против целого дня исступления; огонь пожирает жертву, дрова, камни, землю и воду.", f:"Илия молился секунд тридцать и без крика: устоявшейся вере не нужна громкость. «Пусть откроется сегодня, что Ты — Бог в Израиле»."},
{t:"Дождь возвращается; Илия обгоняет колесницу", r:"3 Цар. 18:41–46", n:"«Вот он, шум ливня»: объявлено под безоблачным небом.", f:"Он услышал дождь верой, когда ещё не было ни одного облака, а потом семь раз посылал слугу посмотреть. Вера слышит первой, выдерживает шесть пустых донесений и бежит впереди доказательств."},
{t:"Огонь в ответ на дерзость", r:"4 Цар. 1:9–15", n:"Два начальника со своими пятьюдесятью погибают; третий подходит смиренно и остаётся жив."},
{t:"Илия разделяет Иордан", r:"4 Цар. 2:8", n:"Плащ ударяет по воде, и вода расходится «вправо и влево»."},
{t:"Илия взят в вихре", r:"4 Цар. 2:11", n:"Огненная колесница и человек, который так и не умер."},
{t:"Елисей разделяет Иордан", r:"4 Цар. 2:13–14", n:"«Где сейчас Господь, Бог Илии?» И только что полученный плащ действует точно так же.", f:"Елисей сразу же пустил в дело то, что получил. Двойную долю он взял тем, что начал ею пользоваться."},
{t:"Исцелённая вода Иерихона", r:"4 Цар. 2:19–22", n:"Соль в новой чаше и слово: «Я исцелил эту воду». Здоровой она остаётся «по сегодняшний день»."},
{t:"Долина наполняется водой", r:"4 Цар. 3:16–20", n:"«Копайте рвы по всей этой долине» (НРП): сначала копай, а вода приходит без ветра и дождя.", f:"Рвы выкопали сухими. Подготовка к ответу — тоже форма веры, и ответ её почитает."},
{t:"Масло вдовы наполняет все сосуды", r:"4 Цар. 4:1–7", n:"Один кувшин масла льётся, пока не наполнится каждый одолженный сосуд, и останавливается только тогда, когда сосуды кончаются.", f:"«Да набери их побольше». Масло не иссякло; иссякли сосуды. Запас ограничивала только вместимость, которую подготовила вера."},
{t:"Воскрешение сына сонамитянки", r:"4 Цар. 4:18–37", n:"Обещанный мальчик умирает в полдень; мать скачет к пророку.", f:"Пока сын лежал мёртвым, она на все вопросы отвечала одним словом: «Здоровы». Она проговорила конец с самого начала и вернулась домой к живому сыну."},
{t:"Смерть в котле исцелена", r:"4 Цар. 4:38–41", n:"Отравленная похлёбка стала безвредной от горсти муки и слова."},
{t:"Сто человек накормлены двадцатью хлебами", r:"4 Цар. 4:42–44", n:"«Они наедятся, и еще останется»: сначала сказано, потом исполнено. У умножения хлебов Иисусом была репетиция."},
{t:"Нееман очищен от проказы", r:"4 Цар. 5:1–14", n:"Сирийский военачальник семь раз окунается в мутную реку и выходит с телом, которое стало «чистым, как у младенца».", f:"Он чуть не упустил исцеление, потому что ждал эффектов: «Я думал, что он непременно выйдет ко мне… поводит рукой над этим местом». Исцеление пришло через смиренное послушание простому слову. Обычно так и бывает."},
{t:"Топор всплывает", r:"4 Цар. 6:1–7", n:"Железо плавает. Бог занимается экономикой встревоженного должника: нет нужды слишком мелкой."},
{t:"Огненные кони вокруг Дофана", r:"4 Цар. 6:15–18", n:"«Тех, кто с нами, больше, чем тех, кто с ними»: у слуги открываются глаза на огненное войско, которое уже стояло там, а вражеское войско уводят ослеплённым.", f:"Видение не успокоило Елисея: он был спокоен до него. Вера видит невидимое как настоящее большинство."},
{t:"Голод в Самарии кончается за день", r:"4 Цар. 7", n:"Цены на муку обваливаются за одну ночь, точно как было предсказано, когда находят брошенный вражеский лагерь.", f:"Сановник, который насмехался: «этого не может быть, даже если Господь откроет небесные окна!», увидел всё своими глазами, но есть так и не стал. Неверие теряет то, чего отказывается ждать."},
{t:"Мёртвый оживает у костей Елисея", r:"4 Цар. 13:20–21", n:"Тело, наспех брошенное в гробницу пророка, встаёт, коснувшись его костей. Помазание пережило человека."},
{t:"Ассирийское войско гибнет за ночь", r:"4 Цар. 19:32–35", n:"185 000 осаждающих мертвы к утру; слово, сказанное Исаией, устояло."},
{t:"Езекия исцелён, добавлено пятнадцать лет", r:"4 Цар. 20:1–6", n:"Смертельное пророчество: «ты умираешь; ты не выздоровеешь», отменено молитвой ещё прежде, чем Исаия успел выйти со двора.", f:"Даже произнесённый смертный приговор склонился перед молитвой. Ни один вердикт не окончателен, пока человек ещё может повернуться лицом к стене и верить."},
{t:"Тень идёт назад", r:"4 Цар. 20:8–11", n:"Тень на ступенях отступает на десять ступенек назад как знамение исцелённому царю."},
{t:"Четвёртый в печи", r:"Дан. 3:19–27", n:"Трое входят связанными; четверо ходят свободно; ни один волос не опалён, нет даже запаха гари.", f:"Их вера была решена до пламени: «Бог, Которому мы служим, может спасти нас… Но даже если нет… мы не будем служить твоим богам». Вера, которая не торгуется."},
{t:"Надпись на стене", r:"Дан. 5", n:"Рука пишет на штукатурке ревизию царства; царство падает той же ночью."},
{t:"Даниил во рву со львами", r:"Дан. 6:16–23", n:"Ночь с голодными львами, и ни царапины.", f:"Текст прямо называет причину: «на нем не оказалось никаких ран, потому что он верил в своего Бога» (ст. 23)."},
{t:"Иона и огромная рыба", r:"Иона 2:1–11", n:"Три дня в глубине и избавление живым: знамение, которое Иисус назвал образцом Своего воскресения (Мф. 12:39–40)."},
{t:"Потоп и одна семья, пронесённая сквозь него", r:"Быт. 6–8", n:"Мир, разобранный и собранный заново водой, и ковчег, построенный ни на чём, кроме предупреждения о том, «чего еще нельзя было видеть».", f:"Евр. 11:7: Ной «в благоговении построил ковчег». Сто двадцать лет стука молотка на одном только слове."},
{t:"Один язык становится многими в Вавилоне", r:"Быт. 11:1–9", n:"Бог смешивает единую речь за одну ночь, и строительство башни останавливается. Первое чудо, направленное на сами слова."},
{t:"Огонь на Содом; жена Лота оглядывается", r:"Быт. 19:24–26", n:"Огонь и сера с неба и женщина, ставшая соляным столбом за то, что обернулась.", f:"Иисус сделал из неё проповедь в одну фразу о раздвоенном внимании: «Помните жену Лота!» (Лк. 17:32)."},
{t:"Исцелён дом Авимелеха", r:"Быт. 20:17–18", n:"Авраам молится, и в доме чужеземного царя открывается всякое закрытое чрево. Первая записанная в Писании молитва об исцелении, и она за чужого."},
{t:"Иаков борется до зари", r:"Быт. 32:24–32", n:"Хватка на всю ночь, после которой у него новое имя и хромота на всю жизнь: «Не отпущу, пока не благословишь меня».", f:"Вера, которую не стряхнуть. Он ушёл с той схватки и всю оставшуюся жизнь ходил иначе."},
{t:"Столп облачный и огненный", r:"Исх. 13:21–22", n:"Сорок лет видимого водительства: тень днём, свет ночью, и они «ни разу не отошли от народа»."},
{t:"Перепела с моря", r:"Исх. 16:13; Чис. 11:31", n:"Ветер с моря приносит перепелов вокруг лагеря на день пути, дважды, по первому требованию."},
{t:"Лицо Моисея сияет", r:"Исх. 34:29–35", n:"Сорок дней в присутствии Бога, и его кожа выносит свет с собой: ему приходится закрывать лицо покрывалом, чтобы на него можно было смотреть.", f:"2 Кор. 3:18: то, что сияло на лице Моисея, должно менять и нас, и «Его слава в нас все возрастает»."},
{t:"Слава наполняет скинию", r:"Исх. 40:34–35", n:"Облако опускается так плотно, что Моисей не может войти. То же самое повторяется при открытии храма Соломона (3 Цар. 8:10–11)."},
{t:"Мор остановлен между живыми и мёртвыми", r:"Чис. 16:46–48", n:"Аарон бежит с кадильницей в самую середину расползающегося мора и встаёт там. «И мор прекратился».", f:"Ходатайство как физическое действие: человек стоит в проломе, прямо на пути беды."},
{t:"Одежда и обувь, которые не износились", r:"Втор. 29:5; Неем. 9:21", n:"Сорок лет в пустыне: «не ветшали ваши одежды, не изнашивались сандалии у вас на ногах». Самое тихое чудо Библии и самое долгое."},
{t:"Гром и дождь во время жатвы пшеницы", r:"1 Цар. 12:16–18", n:"Самуил просит грозы не по сезону, в сухой месяц, как знамения, и получает её в тот же день."},
{t:"Опухоли у филистимлян и возвращение ковчега", r:"1 Цар. 5–6", n:"Дагон падает, пять городов поражены, а две дойные коровы везут ковчег домой в гору, мыча, прочь от своих телят: путь, который ни одно животное не выбрало бы."},
{t:"Ионафан и его оруженосец", r:"1 Цар. 14:6–15", n:"Двое лезут на скалу на одном «может быть»: «Может быть Господь будет действовать нам во благо», и ломается целая застава. Земля дрожит, и Библия говорит: «Этот ужас был послан Богом».", f:"Вера не всегда начинается с уверенности. Она начинается с движения."},
{t:"Узза и ковчег", r:"2 Цар. 6:6–7", n:"Рука, поддержавшая святыню, и человек умирает у повозки. Самая тяжёлая страница летописи, и её не убрали."},
{t:"Рука Иеровоама отсыхает; жертвенник раскалывается", r:"3 Цар. 13:1–6", n:"Царь указывает на пророка, и его рука застывает в воздухе. Он просит молитвы, и та же рука исцеляется."},
{t:"Гиезий получает проказу Неемана", r:"4 Цар. 5:20–27", n:"Слуга гонится за подарком, от которого отказался Елисей, и выходит из комнаты «бел от проказы, как снег». Вторая половина истории Неемана."},
{t:"Разум Навуходоносора возвращён", r:"Дан. 4:25–34", n:"Семь лет он ест траву, как вол, а потом: «мой разум вернулся ко мне». Самый могущественный человек на земле разобран и собран заново, чтобы понять, Кто правит."},
{t:"Иову возвращено вдвое", r:"Иов 42:10–17", n:"«После того как Иов помолился за своих друзей, Господь вернул ему благополучие и дал ему вдвое больше того, что было у него прежде», и ещё сто сорок лет, чтобы этому радоваться."},
{t:"Долина сухих костей", r:"Иез. 37:1–14", n:"Кость к кости, потом жилы, потом плоть, потом дыхание: войско стоит там, где было кладбище. Сначала Иезекииля заставляют пророчествовать костям.", f:"Бог спрашивает его: «могут ли эти кости ожить?», прежде чем делает это. Требовался ответ веры, а не оптимизма."},
// ---------------- ИИСУС ----------------
{t:"Вода в вино", r:"Ин. 2:1–11", n:"Первое знамение: шесть каменных сосудов, одно указание и лучшее вино на празднике.", f:"Совет Марии — весь протокол веры: «Делайте то, что Он вам скажет». Слуги послушались странного слова и сами пронесли чудо в своих кувшинах."},
{t:"Сын царедворца исцелён на расстоянии", r:"Ин. 4:46–54", n:"«Иди, твой сын будет жить»: исцелён в тот же час, за семнадцать миль.", f:"«Человек поверил слову Иисуса и пошел». Ни знамения, ни ощущения, ни сопровождения: он пошёл домой на одной голой фразе. Это и есть должностная инструкция веры."},
{t:"Первый чудесный улов", r:"Лк. 5:1–11", n:"Сети рвутся, две лодки тонут от рыбы после ночи впустую.", f:"«Наставник, мы трудились всю ночь и ничего не поймали, но если Ты так говоришь, то я закину сети». Опыт говорил «нет», слово говорило «да»; Пётр встал на сторону слова."},
{t:"Одержимый в синагоге", r:"Мк. 1:23–27", n:"«Замолчи! Выйди из него!» Изумление толпы: «Он даже нечистым духам приказывает, и те подчиняются Ему!» Освобождение — это приказ, а не переговоры."},
{t:"Тёща Петра исцелена", r:"Лк. 4:38–39", n:"«Иисус приказал горячке покинуть женщину»: Иисус говорил с симптомом, словно тот мог слышать, и он ушёл. Она встала и накрыла на стол."},
{t:"Вечер у дверей: исцелил всех", r:"Мф. 8:16–17", n:"«Он изгнал духов словом и исцелил ВСЕХ больных».", f:"Матфей добавляет причину: «Это было исполнением слов пророка Исаии: „Он взял наши немощи и понес наши болезни“». Исцеление ведёт прямо к Ис. 53: это купленное, а не прихоть."},
{t:"Прокажённый: «Хочу, очистись!»", r:"Мк. 1:40–42", n:"Иисус прикоснулся к неприкасаемому, и проказа сразу ушла.", f:"Прокажённый сомневался только в желании: «Если Ты захочешь». Иисус ответил на вопрос о желании для всех поколений: «Хочу». Вере больше никогда не нужно об этом гадать."},
{t:"Парализованный через крышу", r:"Мк. 2:1–12", n:"Сначала прощение, потом «встань, возьми свою циновку»: доказательство, что у Сына Человеческого есть власть на земле.", f:"«Иисус, УВИДЕВ их веру». Веру было видно: она выглядела как разборка крыши. И это была их вера, во множественном числе: четверо друзей принесли одного человека к его чуду."},
{t:"Расслабленный у Вифезды", r:"Ин. 5:1–9", n:"Тридцать восемь лет ожидания воды кончаются приказом: «Встань! Возьми свою циновку и иди». Приказ нёс в себе силу его исполнить."},
{t:"Иссохшая рука", r:"Мк. 3:1–5", n:"«Протяни руку»: единственное, чего человек не мог сделать.", f:"Сила встретила его посреди послушания: «Тот протянул, и его рука стала совершенно здоровой». Иисус постоянно приказывает невозможное и вкладывает возможное внутрь приказа."},
{t:"Слуга сотника", r:"Мф. 8:5–13", n:"Исцелён в тот же час, на расстоянии, по слову.", f:"«Скажи лишь слово… даже в Израиле Я не встречал такой сильной веры». Иисус удивился. Вера в одно слово, без визита, без прикосновения, без доказательств, — золотой стандарт, который Он назвал."},
{t:"Воскрешение сына вдовы из Наина", r:"Лк. 7:11–17", n:"Иисус прерывает похороны, касается носилок и говорит мёртвому: «Юноша, говорю тебе: встань!» Начало положило сострадание; никто не просил."},
{t:"Буря утихает", r:"Мк. 4:35–41", n:"«Умолкни! Перестань!» И наступил полный штиль.", f:"«Ну, что вы испугались?.. Неужели у вас еще нет веры?» Он уже сказал: «Переправимся на другую сторону озера». Слово содержало исход; буря была просто громким встречным донесением."},
{t:"Легион изгнан в Гадаре", r:"Мк. 5:1–20", n:"Человек, которого не удерживали никакие цепи, сидит одетый и в здравом уме. Тысячи демонов, один приказ."},
{t:"Воскрешение дочери Иаира", r:"Мк. 5:21–24, 35–43", n:"«Талита, кум!» Двенадцатилетняя девочка встаёт и ест.", f:"Против донесения о смерти: «Не бойся, только верь!» А потом Иисус выставил плакальщиков, прежде чем действовать: неверие сначала убрали из комнаты."},
{t:"Женщина с кровотечением", r:"Мк. 5:25–34", n:"Двенадцать лет, все деньги потрачены на врачей, стало хуже, а не лучше, и исцеление от одного прикосновения к краю одежды.", f:"Она УСЛЫШАЛА об Иисусе, она ГОВОРИЛА: «Если я хоть к одежде Его прикоснусь, то исцелюсь», она ДЕЙСТВОВАЛА сквозь толпу, и Он сказал: «твоя вера исцелила тебя!» Слышать, говорить, делать: весь механизм в пяти стихах."},
{t:"Исцеление двух слепых", r:"Мф. 9:27–31", n:"«Вы верите, что Я могу это сделать?»", f:"«Пусть же с вами будет по вашей вере». Вера — мера получения: самая точная фраза о вере, которую произнёс Иисус."},
{t:"Немой одержимый", r:"Мф. 9:32–33", n:"Демон изгнан, немой заговорил, и люди говорят: «Ничего подобного еще не бывало в Израиле»."},
{t:"Назарет: ни одного чуда", r:"Мк. 6:1–6", n:"Античудо: «Он НЕ МОГ совершить там ни одного чуда», лишь исцелил нескольких больных.", f:"«Он удивлялся неверию в этих людях». Единственным записанным ограничителем силы Иисуса была апистия, не-вера. Не трудные случаи. Атмосфера родного города."},
{t:"Насыщение пяти тысяч", r:"Ин. 6:1–14", n:"Пять хлебов, две рыбы, пять тысяч мужчин накормлены, двенадцать корзин осталось: единственное чудо, которое есть во всех четырёх Евангелиях.", f:"Он возблагодарил над очевидной нехваткой. Благодарность прежде, чем хватает, — арифметика веры."},
{t:"Хождение по воде, и Пётр тоже", r:"Мф. 14:22–33", n:"Иисус идёт по воде; Пётр просит слова и получает его: «Иди».", f:"Одно рема удержало человека поверх моря. Он начал тонуть, когда смотрел на ветер, а не на слово: «зачем же ты стал сомневаться?» Сомнение — это раздвоенное внимание."},
{t:"Дочь хананеянки", r:"Мф. 15:21–28", n:"Молчание, потом видимый отказ, а потом: «Женщина, у тебя великая вера! Пусть будет так, как ты хочешь».", f:"Великая вера проходит сквозь любое разочарование и не уходит без благословения. Иисус отдал исход ей в руки: как ты хочешь."},
{t:"Эффата: глухонемой", r:"Мк. 7:31–37", n:"Пальцы в уши, вздох к небу, одно арамейское слово: «Откройся!» «Все, что Он делает — хорошо»."},
{t:"Насыщение четырёх тысяч", r:"Мк. 8:1–9", n:"На этот раз семь хлебов. Ученики уже однажды видели это, и позже Иисус сокрушался, что они так и не поняли про хлебы (Мк. 8:17–21)."},
{t:"Слепой в Вифсаиде", r:"Мк. 8:22–26", n:"Два прикосновения: сначала «вижу людей: словно двигаются деревья», потом всё ясно.", f:"Частичный результат — не окончательный. Иисус не остановился на улучшении: Он прикоснулся снова. И нам не стоит останавливаться."},
{t:"Мальчик с немым и глухим духом", r:"Мк. 9:14–29", n:"Судороги с детства; ученики только что публично потерпели неудачу.", f:"«Если можешь?! — сказал Иисус. — Кто верит, тот может все». Честная смесь отца: «Я верю, но помоги мне преодолеть свое маловерие!» — оказалась достаточной. Неудача учеников получила один диагноз: «Потому что у вас мало веры» (Мф. 17:20)."},
{t:"Монета во рту рыбы", r:"Мф. 17:24–27", n:"Налог к уплате; следующая рыба Петра приносит точную сумму. Обеспечение с чувством юмора."},
{t:"Слепорождённый", r:"Ин. 9", n:"Глина на глазах и странное указание: «пойди и умойся в пруду Силоам».", f:"Он послушался необъяснимого слова и «вернулся зрячим». Его богословие уместилось в одну фразу: «я был слеп, а сейчас вижу!» Опыт, полученный простым послушанием."},
{t:"Слепой и немой одержимый", r:"Мф. 12:22", n:"Слепой и немой, а потом видящий и говорящий. Это чудо породило теорию фарисеев о Веельзевуле: враждебные свидетели признали факт и спорили только об источнике."},
{t:"Женщина, согнутая восемнадцать лет", r:"Лк. 13:10–17", n:"«Женщина! Ты свободна от своей болезни!» И она выпрямилась после восемнадцати лет.", f:"Иисус представил исцеление как право по завету: «Так не нужно ли было освободить… эту женщину, одну из дочерей Авраама… связанную сатаной?» «Не нужно ли»: исцеление как то, что положено по завету, а не особая милость."},
{t:"Человек с водянкой", r:"Лк. 14:1–6", n:"Исцелён в субботу за обеденным столом фарисея, вместе с вопросом, на который им нечего было ответить."},
{t:"Десять прокажённых", r:"Лк. 17:11–19", n:"«Пойдите и покажитесь священникам»: указание, которое имело смысл только после очищения, которого у них ещё не было.", f:"«Те ПОШЛИ и по дороге были исцелены». Вера движется раньше доказательств. Тот, кто вернулся, получил второе слово: «твоя вера спасла тебя»: созо, целостность глубже кожи."},
{t:"Лазарь воскрешён через четыре дня", r:"Ин. 11:1–44", n:"«Лазарь, выходи!» И умерший вышел, прямо в погребальных пеленах.", f:"«Разве Я не говорил тебе, что если ты будешь верить, то увидишь Божью славу?» И Он поблагодарил Отца ПРЕЖДЕ, чем сдвинулся камень. Вера — условие того, чтобы увидеть, а не награда за увиденное."},
{t:"Слепой Вартимей", r:"Мк. 10:46–52", n:"Нищий у дороги кричит громче, когда ему велят молчать, сбрасывает свой плащ и подходит.", f:"«Твоя вера исцелила тебя». Его веру было слышно (крик сквозь шиканье) и видно (брошенный плащ, на котором он просил милостыню) прежде, чем открылись его глаза."},
{t:"Смоковница засохла от корней", r:"Мк. 11:12–24", n:"Проклята за завтраком, засохла к следующему утру: живой наглядный урок Иисуса о вере.", f:"Его комментарий — манифест: «Имейте веру в Бога!.. если кто-то СКАЖЕТ этой горе: „Поднимись и бросься в море!“ — и при этом не будет сомневаться в душе, а будет верить, что произойдет то, что он сказал, то так ему и будет»."},
{t:"Ухо Малха восстановлено", r:"Лк. 22:50–51", n:"Последнее чудо Иисуса перед крестом: исцеление врага, пришедшего Его арестовать, раненного Его же защитником."},
{t:"Второй чудесный улов", r:"Ин. 21:1–14", n:"После воскресения: снова пустая ночь, снова слово: «Забросьте сеть с правого борта», и «сто пятьдесят три большие рыбы, однако сеть не порвалась»."},
{t:"Воскресение Иисуса", r:"Мф. 28; Ин. 20", n:"Чудо под всеми чудесами: сама смерть сломана изнутри. Каждое обещание Евангелия скреплено подписью пустой гробницы.", f:"«Я живу, и поэтому вы тоже будете жить» (Ин. 14:19). Вся вера во все чудеса стоит здесь: Тот, Кто сдержал это обещание, может сдержать любое."},
{t:"Обобщения исцелений: «исцелил их всех»", r:"Мф. 4:23–24; 9:35; 12:15; 14:35–36; Лк. 6:19", n:"Между именованными историями Матфей и Лука снова и снова повторяют припев: целые города у дверей, и «Он исцелил их ВСЕХ». «И все, кто прикасался, выздоравливали».", f:"«Из Него исходила сила, которая всех исцеляла» (Лк. 6:19). Именованные чудеса — образцы, а не опись. Нет ни одного записанного случая, чтобы Иисус отказал в исцелении тому, кто пришёл."},
{t:"Преображение", r:"Мф. 17:1–8", n:"«Лицо Его засияло, как солнце, а одежда стала белой, как свет», рядом Моисей и Илия, и голос из облака: «Это Мой любимый Сын… Слушайте Его!»"},
{t:"Он проходит сквозь толпу в Назарете", r:"Лк. 4:28–30", n:"Толпа подводит Его к краю обрыва, а Он просто проходит посреди них и идёт Своей дорогой. Объяснения не дано."},
{t:"Тьма, разорванная завеса и открытые гробы", r:"Мф. 27:45–53", n:"Три часа тьмы в полдень; храмовая завеса разорвана сверху донизу; землетрясение; и многие тела святых воскрешены и увидены в городе."},
{t:"Вознесение", r:"Деян. 1:9–11", n:"Он поднят у них на глазах, и облако скрывает Его от них, вместе с обещанием, что Он вернётся так же."},
// ---------------- РАННЯЯ ЦЕРКОВЬ ----------------
{t:"Пятидесятница: ветер, огонь и языки", r:"Деян. 2:1–4", n:"Обещанный Дух приходит слышимо и видимо, и церковь рождается говорящей."},
{t:"Хромой у Красных ворот", r:"Деян. 3:1–16", n:"Хромой от рождения, которого каждый день приносили просить милостыню, теперь «ходил, прыгал и прославлял Бога».", f:"«То, что есть, я даю тебе». Пётр знал, что у него есть что передать. Его объяснение толпе: «Имя Его укрепило этого человека… и вера, которая от Него, исцелила его»."},
{t:"Множество исцелённых; тень Петра", r:"Деян. 5:12–16", n:"Больных выносят на улицы на постелях; толпы из окрестных городов, «и все исцелялись». Припев «исцелил их всех» продолжается и после вознесения."},
{t:"Анания и Сапфира", r:"Деян. 5:1–11", n:"Две согласованные лжи Святому Духу; двое похорон. Снова слова, на этот раз смертельные. «Всей церковью… овладел великий страх»."},
{t:"Ангел освобождает апостолов", r:"Деян. 5:17–25", n:"Двери темницы открыты за ночь, с указанием идти прямо обратно проповедовать."},
{t:"Стефан: служитель у столов, полный веры и силы", r:"Деян. 6:8", n:"«Стефан, человек, полный Божьей благодати и силы, совершал в народе великие чудеса и знамения».", f:"Не апостол, а служитель, поставленный раздавать пищу. Требование, которое названо, — быть человеком, «полным веры и Святого Духа» (Деян. 6:5). Знамения никогда не принадлежали должности."},
{t:"Филипп в Самарии", r:"Деян. 8:5–8", n:"Нечистые духи выходят с криком, парализованные и хромые исцелены, «и в городе том была большая радость». Ещё один служитель, ещё один преображённый город."},
{t:"Глаза Савла открыты", r:"Деян. 9:10–18", n:"Злейший враг церкви исцелён от слепоты и наполнен Духом через Ананию, просто «ученика по имени Анания».", f:"Не апостол, не пророк: всё резюме Анании в Писании — «ученик». В Деяниях руки возлагают обычные верующие, и чешуя падает."},
{t:"Эней: восемь лет паралича", r:"Деян. 9:32–35", n:"«Эней! Иисус Христос исцеляет тебя. Встань и собери постель. В тот же момент Эней встал». Целая область обратилась к Господу, увидев это."},
{t:"Тавифа воскрешена из мёртвых", r:"Деян. 9:36–42", n:"Пётр «выслал всех из комнаты», точно так, как видел у Иисуса в доме Иаира, встал на колени и сказал: «Тавита, встань!»"},
{t:"Пётр выходит из темницы", r:"Деян. 12:5–11", n:"Цепи спадают между двумя стражниками; железные ворота открываются сами; молящаяся церковь едва верит собственной отвеченной молитве."},
{t:"Волхв Елима ослеплён", r:"Деян. 13:6–12", n:"Противник Евангелия поражён слепотой «некоторое время», и проконсул верит."},
{t:"Калека в Листре", r:"Деян. 14:8–10", n:"Хромой от рождения, никогда не ходивший, пока не прозвучал громкий приказ: «Встань на ноги твои прямо! Тот вскочил и начал ходить».", f:"Павел «посмотрел на него и увидел, что у того есть вера для исцеления». Вера была видна на лице слушающего человека. Она росла так, как растёт всегда: «он слушал то, что говорил Павел» (ст. 9)."},
{t:"Павел поднимается после побиения камнями", r:"Деян. 14:19–20", n:"Побит камнями, вытащен за город, брошен как мёртвый, но «когда ученики собрались вокруг него, он поднялся и пошел обратно в город»."},
{t:"Освобождение служанки в Филиппах", r:"Деян. 16:16–18", n:"Духу прорицания приказано выйти «во имя Иисуса Христа», и он вышел «в тот же момент»."},
{t:"Филиппийская темница открыта землетрясением", r:"Деян. 16:25–34", n:"Хвала в полночь, землетрясение, все двери открыты, все оковы спали, и к утру уверовал весь дом тюремщика."},
{t:"Особые чудеса: платки и фартуки", r:"Деян. 19:11–12", n:"Ткань, которой касался Павел, приносят больным, «и у них проходили болезни, и злые духи выходили из них».", f:"Как край одежды Иисуса: вера тянется к точке соприкосновения, и Бог это почитает. Сила не в ткани, а в вере, которой дали место, куда опереться."},
{t:"Евтих воскрешён в Троаде", r:"Деян. 20:7–12", n:"Заснул на окне во время долгой проповеди, упал «с третьего этажа», и «когда его подняли, он был мертв». Обнят, поднят и возвращён на собрание живым."},
{t:"Гадюка на Мальте", r:"Деян. 28:1–6", n:"Гадюка впивается Павлу в руку; он стряхивает её в огонь и не чувствует вреда: Мк. 16:18 происходит в летописи, к изумлению островитян."},
{t:"Отец Публия и весь остров", r:"Деян. 28:8–9", n:"Горячка и дизентерия исцелены молитвой и возложением рук; «все больные острова стали приходить и получали исцеление». Летопись Деяний закрывается так же, как шла: все, кто пришёл, исцелены."},
{t:"Место поколебалось, когда они молились", r:"Деян. 4:31", n:"Они просят смелости и знамений, и здание сотрясается. «Они были исполнены Святым Духом и смело возвещали слово Божье»."},
{t:"Филипп перенесён в Ашдод", r:"Деян. 8:39–40", n:"Евнух выходит из воды, а его благовестника уже нет: «Филипп оказался в городе Ашдоде», миль за тридцать вверх по побережью."},
{t:"Ирод поражён", r:"Деян. 12:21–23", n:"Он принимает рукоплескания толпы, называющей его богом, и не отдаёт славу Богу. Глава, которая открылась молящейся церковью, заканчивается мёртвым гонителем, а «слово Божье между тем распространялось все дальше и дальше»."},
{t:"Ни волоса не упадёт", r:"Деян. 27:22–25, 44", n:"Двести семьдесят шесть человек на корабле, который разваливается в двухнедельный шторм, и Павел заранее говорит им исход: «Я доверяю Богу и верю, что все будет так, как мне сказано». Все до одного добрались до суши.", f:"Он не говорит «надеюсь». Он говорит «Я доверяю Богу», а потом называет им счёт."},
// ---------------- ПОСЛЕ БИБЛИИ ----------------
{t:"Раздробленная нога Пьера де Руддера", r:"Остаккер, Бельгия · 1875", n:"Большеберцовая кость, раздробленная упавшим деревом, восемь лет не срасталась: открытая гноящаяся рана, концы кости заметно разошлись. Помолившись у святыни, де Руддер встал и сразу пошёл. После его смерти кости ноги эксгумировали и сфотографировали: перелом сросся без шва, посреди линии излома.", f:"Восемь лет медицинской невозможности закончились одной минутой молитвы и оставили физическое доказательство, на которое можно посмотреть до сих пор.", s:"Осмотрен несколькими врачами до и после; кости сохранены и сфотографированы. Обсуждается в Craig Keener, Miracles (2011)."},
{t:"Семьдесят одно засвидетельствованное исцеление в Лурде", r:"Лурд, Франция · 1858–2024", n:"Из примерно 7000 заявленных исцелений постоянная коллегия врачей, Международный медицинский комитет Лурда, где есть и верующие, и скептики, признала 71 полным, мгновенным, устойчивым и необъяснимым с медицинской точки зрения. Семидесятым стала сестра Бернадетт Морио, которая в 2008 году вышла из сорока лет инвалидности позвоночника; семьдесят первым, подтверждённым в декабре 2024 года, стал Джон Трейнор, исцелённый в 1926 году, первый англоязычный человек в этом списке.", f:"Процедура признания устроена так, чтобы отклонять; планка поставлена против чуда. И всё же семьдесят одно стоит.", s:"Дела Lourdes Medical Bureau и International Medical Committee."},
{t:"Азуза-стрит", r:"Лос-Анджелес · 1906–1909", n:"Пробуждение, которое снова сделало чудесное нормой для современной церкви: три года непрерывных собраний, и исцеления (косоглазие, туберкулёз, искалеченные конечности) из номера в номер описывались в собственной газете миссии.", s:"Газеты The Apostolic Faith, 1906–1908 (сохранились в архивах и доступны сегодня)."},
{t:"Комнаты исцеления Джона Г. Лейка", r:"Спокан, Вашингтон · 1915–1920", n:"Институт божественного исцеления Лейка ежедневно служил больным, и за пять лет были записаны десятки тысяч свидетельств; современники описывали здоровье Спокана в те годы как поразительное.", f:"Лейк обучал обычных верующих, своих «техников исцеления», исходя из убеждения, что Мк. 16 описывает нормальное христианство.", s:"Записи служения и свидетельства собраны в Gordon Lindsay, John G. Lake (1949)."},
{t:"Смит Вигглсворт и воскрешённые", r:"Британия и весь мир · 1900-е–1947", n:"Сантехник из Брадфорда без формального образования оставил несколько независимо подтверждённых рассказов о возвращении умерших, включая его собственную жену Полли, и десятилетия задокументированных исцелений на четырёх континентах.", f:"Весь его метод — главная мысль этого сайта: «Меня не трогает то, что я вижу. Меня трогает только то, во что я верю».", s:"Рассказы собраны в Stanley Frodsham, Smith Wigglesworth: Apostle of Faith (1948)."},
{t:"Проверенные дела Кэтрин Кульман", r:"США · 1950-е–1976", n:"Кардиолог из Калифорнии проследил десять исцелений с собраний Кульман через медицинскую систему (рентген, биопсии, записи до и после), включая ретикулосаркому таза у Лизы Ларьос, и опубликовал доказательства случай за случаем.", s:"H. Richard Casdorph, MD, The Miracles (1976)."},
{t:"Барбара Снайдер встаёт и идёт", r:"Уитон, Иллинойс · 1981", n:"Шестнадцать лет прогрессирующего рассеянного склероза: парализованные ноги, слабеющее зрение, трубка для дыхания. Пока друзья молились, она услышала слова из Ин. 5: «встань… и иди» и сразу встала: лёгкие, ноги и руки здоровы. Её врачи официально подтвердили историю болезни.", f:"Слово, которое она услышала, было рема, сказанным стихом, и исцеление пришло вместе с ним.", s:"Её случай подробно описан, со свидетельствами врачей, в Craig Keener, Miracles vol. 1 (2011)."},
{t:"Голос Дуэйна Миллера на записи", r:"Хьюстон, Техас · 1993", n:"Вирус разрушил его голосовые связки: три года хриплого, сорванного голоса, подтверждённого специалистами. Он преподавал Пс. 102 воскресному классу: «исцеляет все твои болезни», и голос вернулся посреди фразы. Диктофон класса был включён; последующие обследования не нашли рубцовой ткани.", f:"Исцелён, читая вслух стих об исцелении. Вера приходит от слышания, даже когда слышишь свой собственный голос, произносящий Божьи слова.", s:"Запись сохранилась; Duane Miller, Out of the Silence (1996)."},
{t:"Кардиолог и прямая линия", r:"Уэст-Палм-Бич, Флорида · 2006", n:"Джеффа Маркина после обширного инфаркта около сорока минут не было пульса, и его объявили мёртвым. Кардиолог Чонси Крэндалл уже выходил, когда почувствовал побуждение вернуться и помолиться над телом, а потом велел дать ещё один разряд. Сердце пошло; Маркин восстановился без повреждения мозга.", s:"Chauncey Crandall, MD, Raising the Dead (2010); больничная документация."},
{t:"Брюс Ван Натта под грузовиком", r:"Висконсин · 2006", n:"Раздавлен лесовозом: перебиты крупные артерии, разрушена большая часть тонкого кишечника. Он выжил вопреки всем протоколам, а позже снимки показали кишечник там, где его не оставалось столько, чтобы жить.", s:"Медицинские снимки обсуждаются в его книге Saved by Angels (2008); случай отмечен у Keener."},
{t:"Доктор Шон Джордж: 55 минут без жизни", r:"Калгурли, Австралия · 2008", n:"Врач-терапевт с остановкой сердца в сельской больнице: примерно 55 минут реанимации закончились прямой линией, и реанимацию прекратили. Пришла жена, взяла его за руку и помолилась, и на мониторе появился ритм. Он вернулся к врачебной практике и публикует собственные больничные документы.", f:"Собственная история болезни врача, спорящая с материализмом его же почерком.", s:"Документы и ленты монитора опубликованы Dr. Sean George (seangeorge.com.au)."},
{t:"Исследование STEPP: слух восстановлен в Мозамбике", r:"Сельский Мозамбик · 2010", n:"Исследователи измеряли слух и зрение до и после близкой ходатайственной молитвы на деревенских собраниях: статистически значимое улучшение по всей группе, включая людей, которые перешли от порога тяжёлого нарушения к слуху, достаточному для разговора.", f:"Молитва за глухих, измеренная лабораторными приборами и опубликованная в рецензируемом медицинском журнале: Мк. 7 с аудиометром.", s:"Brown et al., «Study of the Therapeutic Effects of Proximal Intercessory Prayer», Southern Medical Journal 103:9 (2010)."},
{t:"Делия Нокс встаёт", r:"Мобил, Алабама · 2010", n:"Двадцать два года парализованная ниже пояса после автокатастрофы, госпел-певица начала двигаться, потом встала, потом сделала шаг на собрании пробуждения, и всё это снято на камеру. В следующие месяцы она сама выходила на сцену.", s:"Видеозапись, Bay of the Holy Spirit Revival, 27 августа 2010."},
{t:"Дэниел Экечукву", r:"Онича, Нигерия · 2001", n:"Смертельно ранен в автокатастрофе, признан мёртвым и отвезён в морг, а через два дня привезён в церковь, где жена настояла на молитве. Во время собрания он ожил. Его врач, работник морга и пасторы дали показания под присягой.", f:"Причина его жены, из Евр. 11: Бог «вознаграждает тех, кто Его ищет». Два дня она действовала по одному стиху.", s:"Письменные показания свидетелей и расследование задокументированы CfaN; разбирается в Keener, Miracles vol. 1."},
{t:"Шестнадцать лет через зонд, а потом ужин", r:"США · 2011", n:"Рождён с тяжёлым гастропарезом, шестнадцать лет питался через еюностомический зонд. После того как незнакомые люди помолились за него на собрании, он поел, и продолжил есть. Вся его история болезни и выздоровление опубликованы как рецензируемое описание клинического случая.", s:"Romez, Zaritzky & Brown, Complementary Therapies in Medicine 43 (2019)."},
{t:"Джон Смит и ледяное озеро", r:"Сент-Чарльз, Миссури · 2015", n:"Четырнадцать лет, около пятнадцати минут под ледяной водой, потом около сорока пяти без пульса. Когда мать вошла в реанимацию и громко помолилась, на мониторе появился пульс. Через шестнадцать дней он вышел полностью здоровым.", s:"Рассказы лечащих врачей; Joyce Smith, The Impossible (2017); пересказано в фильме Breakthrough (2019)."},
{t:"Пробуждение на Гебридах", r:"Остров Льюис, Шотландия · 1949–1952", n:"Две молящиеся сестры за восемьдесят, горстка дьяконов в сарае, а потом присутствие, которое опустилось на остров: целые деревни не спали всю ночь под обличением, церкви заполнялись без всякой человеческой рекламы.", f:"Всё началось с двух ходатаев, державшихся за одно обещание: «Я изолью воду на жаждущую землю», месяцами, вслух.", s:"Свидетельства из первых рук: Duncan Campbell и жители острова."},
{t:"Мари Байи и нобелевский лауреат", r:"Лурд, Франция · 1902", n:"Умирающую от туберкулёзного перитонита, её привезли в Лурд вопреки советам врачей. Рядом скептически наблюдал Алексис Каррель, молодой хирург, который в 1912 году получит Нобелевскую премию по медицине, и он видел, как её сильно вздутый живот опал у него на глазах. Она выздоровела и прожила ещё три десятилетия.", f:"Каррель пришёл опровергнуть и не смог. Единственное, чего он так и не сумел сделать, — отрицать то, что видел своими глазами.", s:"Собственный рассказ Carrel, опубликованный посмертно как The Voyage to Lourdes (1950)."},
{t:"Габриэль Гаргам, двадцать месяцев на зонде", r:"Лурд, Франция · 1901", n:"Железнодорожный почтовый служащий после аварии остался частично парализованным и не мог есть; его признали безнадёжным, суд присудил ему пожизненную компенсацию, а потом его привезли в Лурд почти при смерти. Он ушёл оттуда своими ногами и прожил ещё больше пятидесяти лет.", s:"Французские железнодорожные и судебно-медицинские документы; дело Lourdes Medical Bureau."},
{t:"Рука Джона Трейнора", r:"Лурд, Франция · 1923", n:"Ветеран из Ливерпуля: рука парализована осколком, прошедшим через плечо, эпилепсия, частичный паралич обеих ног, пенсия по 100-процентной инвалидности. После купален он пошёл, и рука заработала; Министерство пенсий в конце концов прекратило выплаты, потому что он зарабатывал на жизнь перевозкой угля.", s:"Дело Lourdes Medical Bureau; британские пенсионные документы."},
{t:"Бедро Витторио Микели на рентгене", r:"Лурд, Франция · 1963", n:"Саркома разъела левую тазовую кость; нога безжизненно висела в гипсе. После купания опухоль исчезла, и, как видно на серии рентгеновских снимков, таз восстановился сам. В заключении о признании отмечено, что подобное восстановление кости медицине просто неизвестно.", f:"Серия снимков — не чувство. «До» и «после» лежат в деле.", s:"International Medical Committee Лурда; признано в 1976 году, с полной серией снимков."},
{t:"Делиция Чиролли, двенадцать лет", r:"Сицилия → Лурд · 1976", n:"Саркома Юинга правого колена; от операции отказались, предлагали только ампутацию, ребёнка отправили домой умирать. Её деревня собрала деньги на поездку в Лурд. Она вернулась, и опухоль исчезла без химиотерапии и без облучения. Позже она стала медсестрой.", s:"Признано International Medical Committee Лурда, 1989."},
{t:"Жан-Пьер Бели встаёт с носилок", r:"Лурд, Франция · 1987", n:"Рассеянный склероз с официальной полной инвалидностью, недержанием и парализованными конечностями. Чувствительность вернулась во время помазания больных; той же ночью он встал и пошёл. Комитет наблюдал за ним двенадцать лет, прежде чем признать случай необъяснимым.", s:"International Medical Committee Лурда; признано в 1999 году."},
{t:"Зрение и походка Сержа Перрена", r:"Лурд, Франция · 1970", n:"Повторяющаяся органическая гемиплегия с поражением глаз из-за нарушений мозгового кровообращения: и зрение, и движение восстановились во время помазания больных.", s:"Признано International Medical Committee Лурда, 1978."},
{t:"Сердце Анны Сантаниелло", r:"Лурд, Франция · 1952", n:"Тяжёлая болезнь Буйо с повреждённым митральным клапаном: синие губы, ни ходьбы, ни лестниц, ни надежды ни на то, ни на другое. Она вышла из купальни, способная ходить, и дожила до 100 лет.", s:"Признано International Medical Committee Лурда, 2005."},
{t:"Данила Кастелли", r:"Лурд, Франция · 1989", n:"Годы бурных, необъяснимых кризов давления, которые не остановили повторные операции. После купален они прекратились совсем, и комитет наблюдал за ней ещё два десятилетия, прежде чем признать исцеление.", s:"Признано International Medical Committee Лурда, 2013."},
{t:"Августин ведёт реестр", r:"Гиппон, Северная Африка · ок. 424", n:"Августин считал, что время чудес прошло. Потом он стал требовать в своей епархии письменных рассказов, заверенных свидетелями, и за два года собрал почти семьдесят в одном только Гиппоне, включая рак груди у женщины и человека, воскресшего на собственных похоронах.", f:"Он изменил мнение из-за доказательств, которые мог проверить. Так и надо.", s:"Augustine, City of God 22.8, с именами и свидетелями."},
{t:"Святой терн и племянница Паскаля", r:"Пор-Рояль, Париж · 1656", n:"У десятилетней Маргерит Перье была слёзная фистула в такой стадии, что задета кость, и хирурги предлагали прижигание. Она закрылась за несколько часов. Семь врачей осмотрели девочку и подписали заключение, а случай официально расследовали и признали.", s:"Подписанные показания врачей, 1656. Её дядей был Блез Паскаль, писавший об этом в Pensées."},
{t:"Дороти Керин встаёт", r:"Лондон · 1912", n:"Пять лет прикованная к постели туберкулёзным менингитом и туберкулёзом брюшной полости, слепая и почти глухая, при свидетелях ей отвели несколько часов жизни. Она села, прошла через комнату и попросила еды. Лондонская пресса писала об этом; основанный ею дом исцеления работает до сих пор.", s:"Заявления лечащих врачей и пресса того времени; её рассказ The Living Touch (1914)."},
{t:"Кампания Чарльза Прайса, проверенная потом", r:"Ванкувер, Канада · 1923", n:"После огромных собраний исцеления комитет, в который входили врачи, сделал то, чего почти никто не делает: через несколько месяцев разыскал заявивших об исцелении и опубликовал результаты: значительное число стойких исцелений рядом со случаями, которые не удержались.", f:"Честная проверка — друг веры, а не враг. Что устояло, то устояло.", s:"Опубликованный отчёт комитета о проверке, 1923–24."},
{t:"Уэльское пробуждение", r:"Уэльс · 1904–1905", n:"Около 100 000 обращений меньше чем за год, без организации, без рекламы и без сборов пожертвований. Самое странное — гражданские документы: у судей пустые списки дел, закрываются пивные, а шахтные пони, по рассказам, растерялись, потому что шахтёры перестали на них ругаться.", s:"Газеты того времени, судебные и шахтные документы."},
{t:"Шаньдунское пробуждение", r:"Китай · 1930-е", n:"Консервативные миссионеры Южных баптистов, по своему богословию не склонные ничего такого ждать, начали сообщать об исцелениях и как минимум об одном воскрешении и писали об этом домой вопреки собственным ожиданиям.", s:"Письма миссионеров; Mary Crawford, The Shantung Revival (1933)."},
{t:"Пхеньянское пробуждение", r:"Корея · 1907", n:"Недели необычайного публичного покаяния, которые на столетие сформировали корейскую церковь и предшествовали её росту в одну из самых молитвенных церквей на земле.", s:"Дневники миссионеров и сообщения того времени."},
{t:"Книги учёта Джорджа Мюллера", r:"Бристоль, Англия · 1836–1898", n:"Мюллер дал кров, пищу и образование более чем 10 000 сирот за шестьдесят лет и ни разу не попросил денег ни у одного человека, сознательно, как публичную демонстрацию того, что Бог отвечает на молитву. Каждый пенни прихода и расхода публиковался в проверенных годовых отчётах.", f:"Он превратил веру в контролируемый эксперимент длиной в шесть десятилетий и опубликовал данные.", s:"Narrative Мюллера и ежегодные проверенные отчёты."},
{t:"Завтрак на триста человек", r:"Бристоль, Англия · 1870-е", n:"В доме нет еды; дети сидят перед пустыми тарелками, а Мюллер благодарит Бога за то, что им предстоит получить. И тут в дверь стучит пекарь с хлебом: он не мог уснуть, думая об этом. А у ворот ломается тележка молочника, и он предлагает бидоны, пока молоко не скисло.", s:"Дневники Мюллера; рассказ Abigail Townsend Luffe, бывшей там ребёнком."},
{t:"Мюллер и туман у Ньюфаундленда", r:"Северная Атлантика · 1877", n:"Туман остановил корабль, а у Мюллера была назначена встреча в Квебеке. Он позвал капитана вниз помолиться, отклонил предложение капитана тоже помолиться: «вы не верите, что Он это сделает», а потом велел ему открыть дверь, потому что тумана больше нет. Его не было.", s:"Рассказ капитана Joseph Dutton, участника событий."},
{t:"Бутылочка витаминов Корри тен Бом", r:"Равенсбрюк, Германия · 1944", n:"Маленькая бутылочка жидких витаминов, тайно пронесённая в барак, всё лилась и лилась: каждый день она давала дозу десяткам больных женщин, неделями после того, как стекло должно было опустеть, пока не пришла новая партия, и тогда она наконец иссякла.", f:"Ответ её сестры был ответом вдовы из Сарепты, вслух: масло не кончается, пока его изливают для кого-то другого.", s:"Corrie ten Boom, The Hiding Place (1971)."},
{t:"Миссия Хадсона Тейлора, которая никогда не просила", r:"Китай · 1865–1905", n:"Китайская внутренняя миссия выросла до более чем 800 миссионеров по одному и тому же правилу: никаких просьб о деньгах, никаких долгов, о нуждах говорят только Богу, а бухгалтерия открыта для проверки.", s:"Документы CIM; Hudson Taylor's Spiritual Secret (1932)."},
{t:"Брат Андрей на пропускных пунктах", r:"Восточная Европа · 1955–1980-е", n:"Библии, сложенные на виду на сиденье машины, и молитва о том, чтобы глаза, которые могут видеть, их не заметили, и так десятилетиями на коммунистических границах, где обыски проходили над грузом, вокруг него и мимо.", s:"Brother Andrew, God's Smuggler (1967); документы Open Doors."},
{t:"Мэролин Форд видит", r:"Теннесси · 1972", n:"Юридически слепая с 1960 года: юношеская макулярная дегенерация, плотная атрофия в каждой центральной ямке, острота зрения хуже 20/400 на обоих глазах. Через двенадцать лет зрение мгновенно вернулось, когда ночью над ней молился муж. Карты 1974 года показывают 20/100 без коррекции; с 2001 по 2017 год — 20/30–20/40 с коррекцией. Макулы так и не стали выглядеть нормально; таблицу она всё равно читала.", f:"Сорок семь лет контрольных карт, опубликованных в медицинском журнале. Летопись пережила спор.", s:"Romez, Freedman, Zaritzky & Brown, «Case report of instantaneous resolution of juvenile macular degeneration blindness after proximal intercessory prayer», EXPLORE 16:5 (2020), рецензируемая статья с офтальмологическими записями до и после. Её собственный рассказ: These Blind Eyes Now See (1997)."},
{t:"Дерево Аннабел Бим", r:"Техас · 2011", n:"Девять лет, хроническая кишечная псевдообструкция и гипомоторика антрального отдела: зависимость от зонда, ежедневные лекарства. Она упала примерно с тридцати футов головой вниз внутрь полого тополя и ушла не только невредимой, но и свободной от болезни, что её специалисты задокументировали как выздоровление.", s:"Записи лечащих врачей в Boston Children's; Christy Beam, Miracles from Heaven (2015)."},
{t:"Врач публикует исцеления в BMJ", r:"Великобритания · 1983", n:"Рекс Гарднер, консультант-акушер, поставил современные задокументированные случаи исцеления, с больничными записями и подтверждениями коллег, рядом с рассказами VII века у Беды и доказывал в ведущем медицинском журнале, что эти параллели заслуживают внимания, а не смущения.", s:"Gardner, «Miracles of healing in Anglo-Celtic Northumbria…», British Medical Journal 287 (1983)."},
{t:"Дела Global Medical Research Institute", r:"США · 2012–наши дни", n:"Постоянная группа врачей и исследователей собирает заявления об исцелении и делает неблагодарную часть работы: достаёт настоящие записи, снимки и патологию до и после, а потом публикует те случаи, которые выдерживают проверку.", s:"Global Medical Research Institute (globalmri.org); описания случаев в рецензируемой литературе."},
{t:"Iris Global в мозамбикской глуши", r:"Мозамбик · 1990-е–наши дни", n:"Служение Ролланда и Хайди Бейкер выросло из горстки церквей в тысячи, и жители раз за разом называют одну и ту же причину, по которой деревня обратилась: они видели, как кто-то исцелился. Исследователи выбрали это место именно потому, что такие заявления здесь часты и их можно проверить.", s:"Документы Iris Global; место исследования Southern Medical Journal 2010 года."},
{t:"Рэнди Кларк везёт приборы в Бразилию", r:"Бразилия · 2010-е", n:"Global Awakening начал брать на свои кампании медицинскую документацию (аудиометрию, офтальмологический скрининг, врачей в команде) и собирать данные до и после прямо на собраниях, а не одни свидетельства.", s:"Проект медицинской документации Global Awakening, в сотрудничестве с GMRI."},
{t:"Африканские кампании Рейнхарда Боннке", r:"Африка · 1975–2019", n:"«Христос для всех народов» проводил собрания с толпами больше миллиона, и свидетельства об исцелении на месте проверяли команды, прежде чем кто-то доходил до микрофона. Именно на нигерийское собрание этого служения принесли Дэниела Экечукву.", s:"Документы кампаний CfaN и снятая на видео проверка свидетельств."},
{t:"Фотографии Т. Л. Осборна", r:"Глобальный Юг · 1950-е–1990-е", n:"Рано изгнанный с миссионерского поля вызовом индуиста доказать то, что он проповедует, Осборн вернулся проповедовать исцеление огромным толпам по всей Африке и Азии и сознательно документировал результаты на фотографиях.", s:"Фотодокументация Осборна и документы кампаний."},
{t:"Карлос Аннакондиа и аргентинское пробуждение", r:"Аргентина · 1980-е–90-е", n:"Кампании под открытым небом с отдельными шатрами для служения освобождения и медицинскими пунктами для проверки, и национальная церковь, заметно изменившаяся за десятилетие.", s:"Рассказы того времени и документы кампаний."},
{t:"Незарегистрированная церковь в Китае", r:"Китай · 1970-е–наши дни", n:"Самый большой рост церкви в новейшей истории произошёл без зданий, без издательств, без институтов и часто без Библий, и опрос за опросом новообращённых называют одну и ту же главную причину: они видели, как кто-то исцелился.", s:"Социологические опросы, обобщённые в Keener, Miracles; академические исследования китайского христианства."},
{t:"Фатима и солнце", r:"Португалия · 13 октября 1917", n:"Толпа, по оценкам, от 30 000 до 70 000 человек, собравшаяся потому, что трое детей заранее объявили знамение, включая журналистов-скептиков, стоявших под дождём, сообщила, что солнце около десяти минут вело себя невозможным образом, а промокшая за много часов одежда после этого оказалась сухой. Толкование оспаривается; заблаговременное объявление и размер толпы — нет.", s:"Португальская пресса того времени, включая светскую антиклерикальную O Século; показания свидетелей."},
{t:"Дюнкерк и день молитвы", r:"Ла-Манш · май–июнь 1940", n:"На 26 мая был объявлен национальный день молитвы. В следующие дни шторм приковал к земле большую часть люфтваффе, а Ла-Манш лежал необычно гладким, и 338 000 человек ушли с пляжей на маленьких судах. Провидение это или метеорология, спорят до сих пор; последовательность событий и цифры — нет.", s:"Пресса того времени и документы Адмиралтейства; национальный день молитвы был объявлен публично."},
{t:"Кольцо света Джона Пейтона", r:"Новые Гебриды (Вануату) · 1860-е", n:"Враждебные островитяне всю ночь окружали дом миссии, а потом отступили, не напав. Годы спустя обратившийся вождь спросил Пейтона, кто были те люди в сияющих одеждах с обнажёнными мечами, что стояли вокруг всего дома.", s:"John G. Paton, Missionary to the New Hebrides: An Autobiography (1889)."},
{t:"Молящийся Хайд и Риз Хауэллс", r:"Индия и Уэльс · 1900-е–1940-е", n:"Два ходатая, чьи жизни читаются как долгие эксперименты над одним утверждением: Хайд в Пенджабе, Хауэллс над Библейским колледжем Уэльса, и современники записывали, о чём конкретно молились и что конкретно получили.", s:"Биографии того времени и документы колледжа."},
{t:"Всемирное досье", r:"Весь мир · продолжается", n:"Двухтомное академическое исследование собрало задокументированные рассказы об исцелении со всех континентов (катаракта, глухота, паралич, воскрешения) и данные опросов, по которым сотни миллионов живущих людей говорят, что были свидетелями божественного исцеления.", f:"Современная летопись не тонкая: она огромна и в основном не изучена. «Все это происходило не в углу» (Деян. 26:26).", s:"Craig Keener, Miracles: The Credibility of the New Testament Accounts (Baker Academic, 2011); описания случаев Global Medical Research Institute (globalmri.org)."},
{t:"Двадцать семь сообщений, одна комиссия", r:"Нидерланды · 2023", n:"Медицинская комиссия разобрала двадцать семь заявленных исцелений по молитве: собирала записи до и после, беседовала с врачами и оценивала каждый случай по тому, что записи действительно подтверждают. Смысл работы — в методе: большинство заявлений его не выдерживает, и исследование так и говорит.", f:"Ценность фильтра — в том, что он задерживает. Летопись, составленная только из прошедших через него случаев, стоит больше тысячи тех, что его никогда не встречали.", s:"«A Case Study of 27 Prayer Healing Reports Evaluated by a Medical Assessment Team in the Netherlands», EXPLORE 19:3 (2023)."},
{t:"Глухая девочка и ЛОР-хирург", r:"Великобритания", n:"Девятилетняя девочка с двусторонней нейросенсорной тугоухостью, той, что не проходит, у которой слух просто вернулся. Её врач это задокументировал, а лечивший её ЛОР-хирург назвал выздоровление необъяснимым.", f:"Ни стадиона, ни кампании, ни знаменитого имени. Большая часть летописи выглядит именно так.", s:"Задокументировано Dr R. F. R. Gardner; обсуждается в Craig Keener, Miracles Today (2021)."}
];
